import{c as d,U as e,j as r,m as o}from"./chunks/framework.DQFmIr4R.js";const p=JSON.parse('{"title":"头部格式","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specification/header.md","filePath":"zh/specification/header.md","lastUpdated":0}'),a={name:"zh/specification/header.md"};function c(n,t,i,s,h,b){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="头部格式" tabindex="-1">头部格式 <a class="header-anchor" href="#头部格式" aria-label="Permalink to “头部格式”">​</a></h1><p>每个 <code>.ttp</code> 文件头部固定为 26 字节。</p><h2 id="字段表" tabindex="-1">字段表 <a class="header-anchor" href="#字段表" aria-label="Permalink to “字段表”">​</a></h2><table tabindex="0"><thead><tr><th>偏移</th><th>大小</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>0</td><td>4</td><td>bytes</td><td>魔数 <code>TTP\\x01</code>（<code>0x54 0x54 0x50 0x01</code>）</td></tr><tr><td>4</td><td>4</td><td>uint32 LE</td><td>版本号，当前为 <code>1</code></td></tr><tr><td>8</td><td>1</td><td>bitfield</td><td>配置字节 0（见下方位域）</td></tr><tr><td>9</td><td>1</td><td>uint8</td><td>保留字节，当前必须为 <code>0</code></td></tr><tr><td>10</td><td>2</td><td>uint16 LE</td><td>当前卷序号，从 <code>1</code> 开始</td></tr><tr><td>12</td><td>2</td><td>uint16 LE</td><td>总卷数，最小为 <code>1</code></td></tr><tr><td>14</td><td>4</td><td>uint32 LE</td><td>本卷数据长度——后跟的置换/压缩数据的字节数</td></tr><tr><td>18</td><td>8</td><td>bytes</td><td>自定义配置字节，官方解析器忽略，默认全 <code>0</code></td></tr><tr><td><strong>26</strong></td><td></td><td></td><td><strong>头部总长</strong></td></tr></tbody></table><h2 id="配置字节-0-位域" tabindex="-1">配置字节 0 位域 <a class="header-anchor" href="#配置字节-0-位域" aria-label="Permalink to “配置字节 0 位域”">​</a></h2><table tabindex="0"><thead><tr><th>位</th><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>b0</td><td><strong>Flat</strong></td><td><code>0</code> = 目录树模式（允许子目录）；<code>1</code> = 扁平模式（无子目录）</td></tr><tr><td>b1–b2</td><td><strong>Compression</strong></td><td><code>00</code> → LZMA（默认），<code>01</code> → Brotli，<code>10</code> → Deflate，<code>11</code> → 保留（实现应回退为 LZMA）</td></tr><tr><td>b3</td><td><strong>ExtInfo</strong></td><td>仅当 Flat=1 有效：<code>0</code> = 标准扁平，<code>1</code> = 扩展扁平（64 位文件数 + ZIP64 式大小扩展）</td></tr><tr><td>b4</td><td><strong>HasCustom</strong></td><td><code>0</code> = 无自定义数据段，<code>1</code> = 载荷尾部包含自定义数据段</td></tr><tr><td>b5–b7</td><td>保留</td><td>必须为 <code>0</code></td></tr></tbody></table><h2 id="编码示例" tabindex="-1">编码示例 <a class="header-anchor" href="#编码示例" aria-label="Permalink to “编码示例”">​</a></h2><p>假设一个扁平模式、LZMA 压缩、启用了扩展信息、有自定义数据段的单卷文件：</p><table tabindex="0"><thead><tr><th>字段</th><th>值</th></tr></thead><tbody><tr><td>Flat</td><td>1 → bit0 = 1</td></tr><tr><td>Compression</td><td>LZMA → bits1-2 = 00</td></tr><tr><td>ExtInfo</td><td>1 → bit3 = 1</td></tr><tr><td>HasCustom</td><td>1 → bit4 = 1</td></tr><tr><td><strong>config byte 0</strong></td><td>`1</td></tr></tbody></table>',9)])])}const f=d(a,[["render",c]]);export{p as __pageData,f as default};
